import { ArrowUpRight, Check, HelpCircle, Shield, X } from "react-feather";
import { Button, Flex, Text, styled as uiStyled, useSporeColors } from "ui/src";
import { Modal } from "uniswap/src/components/modals/Modal";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const CloseIcon = uiStyled(Flex, {
  cursor: "pointer",
  padding: "$spacing8",
  borderRadius: "$roundedFull",
  hoverStyle: { backgroundColor: "$surface2" }
});
const ModalHeader = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing24"
});
const InfoCard = uiStyled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  padding: "$spacing24",
  flexDirection: "column",
  gap: "$spacing12",
  width: "100%",
  marginBottom: "$spacing24"
});
const OverlappingLogos = uiStyled(Flex, {
  flexDirection: "row",
  position: "relative",
  width: 64,
  height: 40
});
const LogoWrapper = uiStyled(Flex, {
  position: "absolute",
  borderRadius: "$roundedFull",
  borderWidth: 2,
  borderColor: "$surface2",
  overflow: "hidden"
});
const Badge = uiStyled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  px: "$spacing8",
  py: "$spacing2",
  alignItems: "center",
  justifyContent: "center"
});
const Divider = uiStyled(Flex, {
  height: 1,
  backgroundColor: "$surface3",
  width: "100%",
  my: "$spacing16"
});
const AddressPill = uiStyled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  px: "$spacing12",
  py: "$spacing4",
  flexDirection: "row",
  alignItems: "center",
  gap: "$gap4",
  cursor: "pointer"
});
const ProgressBarContainer = uiStyled(Flex, {
  height: 4,
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  width: "100%",
  overflow: "hidden",
  mt: "$spacing24"
});
const ProgressBarFill = uiStyled(Flex, {
  height: "100%",
  backgroundColor: "$accent1",
  backgroundImage: "linear-gradient(90deg, #fbfbfbff 0%, #e0e0e0ff 100%)",
  width: "75%"
  // Mock progress
});
const Spinner = uiStyled(Flex, {
  width: 20,
  height: 20,
  borderRadius: "$roundedFull",
  borderWidth: 2,
  borderColor: "$accent1",
  borderTopColor: "transparent"
});
const DoneButton = uiStyled(Button, {
  py: "$spacing20"
});
const SuccessCircle = uiStyled(Flex, {
  width: 20,
  height: 20,
  borderRadius: "$roundedFull",
  backgroundColor: "$greenVibrant",
  justifyContent: "center",
  alignItems: "center"
});
export default function AutoDeleverageConfirmModal({
  isOpen,
  onClose,
  position
}) {
  const [isDone, setIsDone] = useState(false);
  const colors = useSporeColors();
  const collateralToken = position.collateral.token;
  const borrowToken = position.loan.token;
  const liquidationLtv = 62.5;
  const autoDeleverageLtv = 56.25;
  useEffect(() => {
    if (isOpen && !isDone) {
      const timer = setTimeout(() => setIsDone(true), 3e3);
      return () => clearTimeout(timer);
    }
    if (!isOpen) {
      setIsDone(false);
    }
    return void 0;
  }, [isOpen, isDone]);
  const handleDone = () => {
    setIsDone(false);
    onClose();
  };
  return <Modal
    name={"AutoDeleverageConfirmModal"}
    isModalOpen={isOpen}
    onClose={onClose}
    backgroundColor={colors.surface1.val}
    maxWidth={480}
    padding="$spacing24"
  >
      <style>
        {`
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
          .animate-spin {
            animation: spin 1s linear infinite;
          }
        `}
      </style>

      {
    /* Header */
  }
      <ModalHeader>
        <Text variant="heading2" color="$neutral1">
          Confirm
        </Text>
        <CloseIcon onPress={onClose}>
          <X size={24} color={colors.neutral2.val} />
        </CloseIcon>
      </ModalHeader>

      {
    /* Info Card */
  }
      <InfoCard>
        <Flex flexDirection="row" alignItems="center" gap="$gap16">
          <OverlappingLogos>
            <LogoWrapper left={0} zIndex={2}>
              <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.name ?? ""}
    images={[getTokenLogoUrl(collateralToken.id) || void 0]}
    size={40}
  />
            </LogoWrapper>
            <LogoWrapper left={24} zIndex={1}>
              <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.name ?? ""}
    images={[getTokenLogoUrl(borrowToken.id) || void 0]}
    size={40}
  />
            </LogoWrapper>
          </OverlappingLogos>
          <Flex flexDirection="column" gap="$gap4">
            <Text variant="heading3" color="$neutral1">
              {collateralToken.symbol} / {borrowToken.symbol}
            </Text>
            <Flex flexDirection="row" gap="$gap8" alignItems="center">
              <Badge>
                <Text variant="body4" color="$neutral2">
                  {liquidationLtv}%
                </Text>
              </Badge>
              <ArrowUpRight size={14} color={colors.neutral2.val} />
            </Flex>
          </Flex>
        </Flex>

        <Divider />

        <Flex flexDirection="column" gap="$gap12">
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <Text variant="body3" color="$neutral2">
              Enable Auto Deleverage Liq. LTV
            </Text>
            <HelpCircle size={16} color={colors.neutral3.val} />
          </Flex>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <Shield size={20} color={colors.accent1.val} />
            <Text variant="heading1" color="$neutral1">
              {autoDeleverageLtv}%
            </Text>
          </Flex>
        </Flex>
      </InfoCard>

      {!isDone ? <>
          {
    /* Progress Section */
  }
          <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
            <Text variant="body2" color="$neutral1">
              Authorize Auto-Deleverage contract
            </Text>
            <Flex flexDirection="row" alignItems="center" gap="$gap12">
              <AddressPill>
                <Text variant="monospace" color="$neutral2">
                  0xBBBB...FFCb
                </Text>
                <ArrowUpRight size={14} color={colors.neutral2.val} />
              </AddressPill>
              <Spinner className="animate-spin" />
            </Flex>
          </Flex>

          <ProgressBarContainer>
            <ProgressBarFill />
          </ProgressBarContainer>

          <Text variant="body4" color="$neutral3" mt="$spacing24">
            Signature 1 / 1 - Proceed in your wallet
          </Text>
        </> : <>
          <Flex flexDirection="row" justifyContent="space-between" alignItems="center" mb="$spacing24">
            <Text variant="body2" color="$neutral1">
              Auto-Deleverage enabled!
            </Text>
            <SuccessCircle>
              <Check size={14} color="white" />
            </SuccessCircle>
          </Flex>
          <DoneButton onPress={handleDone}>Done</DoneButton>
        </>}
    </Modal>;
}
