"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useMorphoMarkets, useMorphoUserAllBorrowPositions } from "hooks/morpho";
import { useMemo } from "react";
import { ArrowUpRight } from "react-feather";
import { Button, Flex, Text, styled, useSporeColors } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { useAccount } from "wagmi";
import { useBorrowContext } from "../ContextProvider";
import { transformMorphoBorrowPositionToPositionData } from "../utils";
const CardWrapper = styled(Flex, {
  flexDirection: "column",
  width: "100%",
  gap: "$spacing16"
});
const Card = styled(Flex, {
  flexDirection: "column",
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  borderWidth: 1,
  borderColor: "$surface3Hovered",
  p: "$spacing24",
  gap: "$spacing24"
});
const LabelText = styled(Text, {
  color: "$neutral2",
  variant: "body2",
  $sm: {
    variant: "body3"
  }
});
const ValueText = styled(LabelText, {
  color: "$neutral1"
});
const Divider = styled(Flex, {
  height: 1,
  width: "100%",
  backgroundColor: "$surface3"
});
const ActionButton = styled(Button, {
  borderRadius: "$roundedFull",
  py: "$spacing12"
});
const DataRow = ({ label, value, subValue }) => <Flex row justifyContent="space-between" alignItems="center" width="100%">
    <LabelText color="$neutral2">{label}</LabelText>
    <Flex row alignItems="center" gap={"$spacing8"}>
      <ValueText color="$neutral1">{value}</ValueText>
      {subValue && <Flex backgroundColor="$surface3" px="$spacing8" py="$spacing2" borderRadius="$roundedFull">
          <Text variant="body4" color="$neutral2">
            {subValue}
          </Text>
        </Flex>}
    </Flex>
  </Flex>;
const SliderTrack = styled(Flex, {
  height: 4,
  width: "100%",
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  position: "relative"
});
const SliderFill = styled(Flex, {
  height: "100%",
  backgroundColor: "$greenVibrant",
  // or appropriate health color
  borderRadius: "$roundedFull"
});
export default function PositionCard() {
  const { formatFiatPrice } = useFormatter();
  const colors = useSporeColors();
  const { openTransaction } = useBorrowContext();
  const chainId = UniverseChainId.Mainnet;
  const { address: userAddress } = useAccount();
  const { data: userPositions } = useMorphoUserAllBorrowPositions(userAddress, chainId);
  const { data: markets } = useMorphoMarkets(chainId);
  const positions = useMemo(() => {
    if (!userPositions || !markets) return [];
    return userPositions.map((position) => {
      const market = markets.find((m) => m.id.toLowerCase() === position.marketId.toLowerCase());
      const borrowRate = market?.borrowRate ?? 0;
      const collateralPriceUsd = market?.collateralPriceUsd ?? 0;
      const loanPriceUsd = market?.loanPriceUsd ?? 1;
      return transformMorphoBorrowPositionToPositionData(position, borrowRate, collateralPriceUsd, loanPriceUsd);
    });
  }, [userPositions, markets]);
  if (!userAddress) {
    return <CardWrapper>
        <Flex centered py="$spacing24">
          <Text variant="body2" color="$neutral2">
            Connect wallet to view positions
          </Text>
        </Flex>
      </CardWrapper>;
  }
  if (!positions.length) {
    return null;
  }
  return <CardWrapper>
      {positions.map((position) => <Card key={position.id}>
          {
    /* Header */
  }
          <Flex row justifyContent="space-between" alignItems="center" width="100%">
            <Flex row alignItems="center" gap="$gap12">
              <Flex row alignItems="center">
                <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={position.collateral.token.symbol}
    tokenName={position.collateral.token.name}
    images={[getTokenLogoUrl(position.collateral.token.id) || void 0]}
    size={32}
  />
                <Flex style={{ marginLeft: -12 }}>
                  <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={position.loan.token.symbol}
    tokenName={position.loan.token.name}
    images={[getTokenLogoUrl(position.loan.token.id) || void 0]}
    size={32}
  />
                </Flex>
              </Flex>
              <Flex row alignItems="center" gap="$gap8">
                <LabelText color="$neutral1">
                  {position.collateral.token.symbol}/{position.loan.token.symbol}
                </LabelText>
                {
    /* 
      Note: lltv is not directly available in PositionData as currently defined in types.ts.
      However, it was available in table data previously by transforming?
      Checking table: PositionTable uses transformMorphoBorrowPositionToPositionData.
      The interface PositionData in types.ts DOES NOT have lltv.
      The transformMorphoBorrowPositionToPositionData in utils.ts DOES NOT return lltv.
      Wait, looking at my previous PositionCard code which had mock data, it accessed position.lltv.
      I need to check if lltv is needed. The original image/mock usually implies it.
      Let's check PositionTable columns.
      PositionTable columns: Collateral, Loan, Rate, Health, Utilization.
      No LLTV column in PositionTable.
      
      However, BorrowCard had LLTV in header. PositionCard might not need it if table doesn't have it.
      But wait, PositionCard mock data had LLTV.
      If I want to show LLTV in PositionCard, I need to add it to PositionData.
      Let's check MorphoUserBorrowPosition source or how to get it.
      Market has lltvPercent.
      In transformMorphoBorrowPositionToPositionData, we have access to market via caller map logic, BUT the function signature takes discrete values.
      
      Actually, PositionCard mock UI shows LLTV in the header "LLTV: {position.lltv}%".
      So I should probably add lltv to PositionData.
    */
  }
                <ArrowUpRight size={18} color={colors.neutral2.val} />
              </Flex>
            </Flex>
            <ValueText color={"$neutral1"}>{position.rate.toFixed(2)}%</ValueText>
          </Flex>

          <Divider />

          {
    /* Stats */
  }
          <Flex flexDirection="column" gap="$gap16">
            <DataRow
    label="Collateral"
    value={`${position.collateral.amount.toFixed(2)} ${position.collateral.token.symbol}`}
    subValue={formatFiatPrice({ price: position.collateral.value, type: NumberType.FiatTokenStats })}
  />
            <DataRow
    label="Loan"
    value={`${position.loan.amount.toFixed(2)} ${position.loan.token.symbol}`}
    subValue={formatFiatPrice({ price: position.loan.value, type: NumberType.FiatTokenStats })}
  />
            <DataRow label="Utilization" value={`${position.utilization.toFixed(2)}%`} />
            <DataRow label="Health Factor" value={position.health} />
          </Flex>

          <Divider />

          {
    /* LTV Slider Area - Optional/Mock for now as we don't have max LTV easily accessible in current data shape without market lookups inside component or adding to PositionData */
  }

          <Flex flexDirection="column" gap="$gap12">
            <SliderTrack>
              <SliderFill width={`${position.utilization}%`} />
            </SliderTrack>
            <Flex row justifyContent="space-between">
              <LabelText>LTV: {position.utilization.toFixed(2)}%</LabelText>
            </Flex>
          </Flex>

          <Divider />

          <Flex flexDirection="row" gap="$spacing18" justifyContent="space-between">
            <ActionButton flex={1} onPress={() => openTransaction(position, "borrow")}>
              Borrow
            </ActionButton>
            <ActionButton flex={1} emphasis="secondary" onPress={() => openTransaction(position, "repay")}>
              Repay
            </ActionButton>
          </Flex>
        </Card>)}
    </CardWrapper>;
}
